import"./ViewTransitions.astro_astro_type_script_index_0_lang.77775e67.js";const n=document.getElementById("publish-form"),e=document.getElementById("status-msg"),s=document.getElementById("submit-btn");n?.addEventListener("submit",async o=>{o.preventDefault(),s.disabled=!0,e.innerText="Publishing to GitHub...";const i={secret:document.getElementById("secret").value,title:document.getElementById("title").value,description:document.getElementById("description").value,tags:document.getElementById("tags").value,content:document.getElementById("content").value};try{const t=await fetch("/api/publish",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify(i)}),l=await t.json();t.ok?(e.innerText="🚀 Published! Vercel is now building your new post live.",n.reset()):e.innerText=`❌ Error: ${l.message}`}catch{e.innerText="❌ Network error. Check your connection."}finally{s.disabled=!1}});
